import{_ as n,a as o,c as s,ac as a}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第一册：英语初阶 · 单元 1 语法总结","description":"L1–L24 规则、例句、易错点。","frontmatter":{"title":"第一册：英语初阶 · 单元 1 语法总结","description":"L1–L24 规则、例句、易错点。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","summary":"L1–L24 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 单元 1：身份、物品与基本问答","link":"/life/english/new-concept/book-1/unit-01/overview"},"next":{"text":"第一册：英语初阶 · 单元 1 单词与短语","link":"/life/english/new-concept/book-1/unit-01/vocabulary"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 单元 1：身份、物品与基本问答","link":"/life/english/new-concept/book-1/unit-01/overview"},"next":{"text":"第一册：英语初阶 · 单元 1 单词与短语","link":"/life/english/new-concept/book-1/unit-01/vocabulary"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-01/grammar.md","filePath":"life/english/new-concept/book-1/unit-01/grammar.md"}'),t={name:"life/english/new-concept/book-1/unit-01/grammar.md"};function r(i,e,h,p,l,c){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="第一册-英语初阶-·-单元-1-语法总结" tabindex="-1">第一册：英语初阶 · 单元 1 语法总结 <a class="header-anchor" href="#第一册-英语初阶-·-单元-1-语法总结" aria-label="Permalink to &quot;第一册：英语初阶 · 单元 1 语法总结&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/unit-01/overview">单元导读</a> · <a href="/life/english/new-concept/book-1/unit-01/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-1/unit-01/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-1/unit-01/review">单元复习与自测</a></p><h2 id="be-动词的一般疑问句" tabindex="-1">be 动词的一般疑问句 <a class="header-anchor" href="#be-动词的一般疑问句" aria-label="Permalink to &quot;be 动词的一般疑问句&quot;">​</a></h2><p>含 be 的陈述句变一般疑问句时，将 be 移到主语之前。this 指近处单数物品，回答时通常用 it。简短肯定回答必须保留 is，不能以 Yes, it&#39;s. 结尾。your 是物主限定词，后面接名词，不随物品的数量改变；礼貌开场和确认信息是两个不同的交际步骤。</p><p><strong>L1 原创例句：</strong> Is this your ticket?</p><p>这是你的票吗？</p><p><strong>L2 原创例句：</strong> Is this your notebook?</p><p>这是你的笔记本吗？</p><p><strong>易错：</strong> 问句中的 this 不在回答中机械重复；用 Yes, it is.，不要写 Yes, this.</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-001">Lesson 1</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-002">Lesson 2</a></p><h2 id="be-动词的否定和缩写" tabindex="-1">be 动词的否定和缩写 <a class="header-anchor" href="#be-动词的否定和缩写" aria-label="Permalink to &quot;be 动词的否定和缩写&quot;">​</a></h2><p>否定句在 be 后加 not。is not 可缩为 isn&#39;t；this is 的主语指单数物品。否定回答应先表明不是，再补充正确归属。my、your 后必须接名词；不能把否定词放在名词前来替代谓语否定。sorry 用于表达歉意，excuse me 多用于打扰前引起注意，语境不同。</p><p><strong>L3 原创例句：</strong> This is not my umbrella.</p><p>这不是我的伞。</p><p><strong>L4 原创例句：</strong> That is not your coat.</p><p>那不是你的外套。</p><p><strong>易错：</strong> 不要用 This not my ...；英语完整陈述句通常仍需 be。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-003">Lesson 3</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-004">Lesson 4</a></p><h2 id="身份介绍与特殊疑问句" tabindex="-1">身份介绍与特殊疑问句 <a class="header-anchor" href="#身份介绍与特殊疑问句" aria-label="Permalink to &quot;身份介绍与特殊疑问句&quot;">​</a></h2><p>介绍某人可以用 This is + 姓名。描述国籍通常用 be + 国籍形容词，不加 a。what make 询问品牌，make 在这里是名词；特殊疑问句常用疑问词组 + be + 主语。单数职业名词一般需要 a/an，品牌专名通常不用不定冠词。不要把国籍形容词与国家名混用。</p><p><strong>L5 原创例句：</strong> This is Eva. She is German.</p><p>这是伊娃，她是德国人。</p><p><strong>L6 原创例句：</strong> What make is your camera?</p><p>你的相机是什么牌子的？</p><p><strong>易错：</strong> He is France 应改为 He is French；国家名可用于 from France。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-005">Lesson 5</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-006">Lesson 6</a></p><h2 id="a-an-与职业名词" tabindex="-1">a/an 与职业名词 <a class="header-anchor" href="#a-an-与职业名词" aria-label="Permalink to &quot;a/an 与职业名词&quot;">​</a></h2><p>单数可数职业名词作表语时一般加 a 或 an。选择取决于紧接着的读音，不是字母名称；engineer 前用 an，teacher 前用 a。What is your job? 询问职业，回答可用 I am a/an ...。be 必须与主语一致：I am、you are、he/she is；不能用职业名词直接作谓语。</p><p><strong>L7 原创例句：</strong> My sister is an engineer.</p><p>我姐姐是一名工程师。</p><p><strong>L8 原创例句：</strong> Are your parents teachers?</p><p>你的父母是教师吗？</p><p><strong>易错：</strong> 复数职业前不加 a/an；teachers 与 are 配合，不能写 a teachers。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-007">Lesson 7</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-008">Lesson 8</a></p><h2 id="be-形容词" tabindex="-1">be + 形容词 <a class="header-anchor" href="#be-形容词" aria-label="Permalink to &quot;be + 形容词&quot;">​</a></h2><p>形容词表示状态或性质，常放在 be 后作表语。英语一般不能像中文一样直接说“我很好”而省略 be。How are you? 询问近况，不等于询问身份；其回答可用 I am well/fine。look at 中 at 后接观察对象。形容词通常不因名词单复数增加 s。</p><p><strong>L9 原创例句：</strong> Our new neighbour is very friendly.</p><p>我们的新邻居很友好。</p><p><strong>L10 原创例句：</strong> Look at the young artist.</p><p>看那位年轻的艺术家。</p><p><strong>易错：</strong> He friendly 缺少 be；friendly 在这里是形容词，不是动作动词。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-009">Lesson 9</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-010">Lesson 10</a></p><h2 id="whose-与物主限定词" tabindex="-1">whose 与物主限定词 <a class="header-anchor" href="#whose-与物主限定词" aria-label="Permalink to &quot;whose 与物主限定词&quot;">​</a></h2><p>whose 询问“谁的”，可接名词构成 Whose shirt is this?。回答用 my/your/his/her + 名词；his 可直接放在名词前，her 表示女性所属。whose 与 who&#39;s 不同，后者是 who is 或 who has 的缩写。谈到具体物品时要保持 this/that 与单数、these/those 与复数一致。</p><p><strong>L11 原创例句：</strong> Whose scarf is that?</p><p>那是谁的围巾？</p><p><strong>L12 原创例句：</strong> This is his bicycle.</p><p>这是他的自行车。</p><p><strong>易错：</strong> 不要将 Whose 写成 Who&#39;s；who is 不表示所有关系。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-011">Lesson 11</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-012">Lesson 12</a></p><h2 id="形容词位置与颜色问句" tabindex="-1">形容词位置与颜色问句 <a class="header-anchor" href="#形容词位置与颜色问句" aria-label="Permalink to &quot;形容词位置与颜色问句&quot;">​</a></h2><p>颜色、大小等形容词可放在名词前，也可放在 be 后。单数名词前的冠词放在形容词前，如 a blue jacket。询问颜色用 What colour is/are ...?，be 与所问物品的单复数一致。多个形容词的排序初学阶段先掌握“新旧 + 颜色 + 名词”，如 a new blue jacket。</p><p><strong>L13 原创例句：</strong> Her new jacket is green.</p><p>她的新夹克是绿色的。</p><p><strong>L14 原创例句：</strong> What colour are your shoes?</p><p>你的鞋是什么颜色的？</p><p><strong>易错：</strong> shoes 为复数，问颜色用 are；颜色形容词不变成 greens。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-013">Lesson 13</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-014">Lesson 14</a></p><h2 id="名词复数与复数-be" tabindex="-1">名词复数与复数 be <a class="header-anchor" href="#名词复数与复数-be" aria-label="Permalink to &quot;名词复数与复数 be&quot;">​</a></h2><p>多数可数名词复数加 s；以 s、sh、ch 等结尾常加 es。you 既可指一人也可指多人，be 都用 are。we 和 they 也用 are。these/those 指复数对象，不能与 is 或单数 passport 搭配。称呼多人时，your 本身不加 s；数量信息由后面的名词体现。</p><p><strong>L15 原创例句：</strong> These tourists are from Spain.</p><p>这些游客来自西班牙。</p><p><strong>L16 原创例句：</strong> Are these your passports?</p><p>这些是你们的护照吗？</p><p><strong>易错：</strong> these 是复数；不能说 These is your passport。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-015">Lesson 15</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-016">Lesson 16</a></p><h2 id="复数职业与-their" tabindex="-1">复数职业与 their <a class="header-anchor" href="#复数职业与-their" aria-label="Permalink to &quot;复数职业与 their&quot;">​</a></h2><p>their 用于说明“他们/她们/它们的”，后面既能接单数也能接复数名词，取决于被拥有的东西。多人职业可用 They are engineers；复数泛指职业不加 a/an。What are their jobs? 中 jobs 与 are 对应。介绍名单时用人名说明对象，再用 they 避免机械重复。</p><p><strong>L17 原创例句：</strong> Maya and Leo are office assistants.</p><p>玛雅和利奥是办公室助理。</p><p><strong>L18 原创例句：</strong> Their office is on the first floor.</p><p>他们的办公室在一楼。</p><p><strong>易错：</strong> their 不等于 they are；后者缩写为 they&#39;re。多人可以共用一个 office，不能只看 their 就加复数。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-017">Lesson 17</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-018">Lesson 18</a></p><h2 id="主格和宾格" tabindex="-1">主格和宾格 <a class="header-anchor" href="#主格和宾格" aria-label="Permalink to &quot;主格和宾格&quot;">​</a></h2><p>主语位置用 I/he/she/we/they，动词或介词后的宾语位置用 me/him/her/us/them。Look at 后需要宾格，如 Look at them。形容词描述人的状态时仍需要 be；多个形容词可用 and 连接。先判断代词在句中的角色，再决定形式，不要只按中文“他们”选 they。</p><p><strong>L19 原创例句：</strong> The runners are tired and hungry.</p><p>跑步的人又累又饿。</p><p><strong>L20 原创例句：</strong> Look at them near the gate.</p><p>看门附近的他们。</p><p><strong>易错：</strong> look at they 应改为 look at them；they 在此不是主语。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-019">Lesson 19</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-020">Lesson 20</a></p><h2 id="which-与-one-的替代" tabindex="-1">which 与 one 的替代 <a class="header-anchor" href="#which-与-one-的替代" aria-label="Permalink to &quot;which 与 one 的替代&quot;">​</a></h2><p>which 用于在可识别的范围中选择。one 可以替代前面已提到的单数可数名词，以避免重复；如 the red one 表示红色的那个。give 可接双宾语：give + 人 + 物，人的位置用宾格。形容词前是否加 the 取决于是否指向特定选项，不是所有 one 都必须带 the。</p><p><strong>L21 原创例句：</strong> Please give me the empty box.</p><p>请把那个空盒子给我。</p><p><strong>L22 原创例句：</strong> Which notebook do you want: the red one or the blue one?</p><p>你要哪本笔记本：红的还是蓝的？</p><p><strong>易错：</strong> one 替代可数名词单数，不能用来替代不可数的 water。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-021">Lesson 21</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-022">Lesson 22</a></p><h2 id="ones-与复数选择" tabindex="-1">ones 与复数选择 <a class="header-anchor" href="#ones-与复数选择" aria-label="Permalink to &quot;ones 与复数选择&quot;">​</a></h2><p>ones 替代已提到的复数可数名词；the clean ones 指前文的一组干净物品。some 后可接复数可数名词，也可接不可数名词；本课先用 some plates 这样的复数对象。give us/them 中代词是宾格。which glasses 的中心词为复数，回答时不要退回单数 one。</p><p><strong>L23 原创例句：</strong> Please give us the clean plates.</p><p>请把干净的盘子给我们。</p><p><strong>L24 原创例句：</strong> I want the small ones beside the sink.</p><p>我要水槽旁边小的那些。</p><p><strong>易错：</strong> 不能把复数 plates 替换为 one；some 后单数 plate 通常不表示“一些盘子”。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-023">Lesson 23</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-024">Lesson 24</a></p>',98)])])}const b=n(t,[["render",r]]);export{u as __pageData,b as default};
